import random

def is_graceful(labels, edges):
    edge_labels = set()
    for u, v in edges:
        diff = abs(labels[u] - labels[v])
        if diff in edge_labels or diff == 0 or diff > 33:
            return False
        edge_labels.add(diff)
    return len(edge_labels) == 33

